# `make test` runs every gate and fails at the end, so a CLI failure does not hide the terminal-scope or
# security result. It calls the two halves of `npm --prefix cli test` by name (test:cli, test:scope), so the
# step list lives only in cli/package.json.
# CI evaluator fixtures (tmpfs workspace and runtime root) come from `make test-ci`; see docs/DEVELOPMENT.md.
test: test-fixture-notice
	@rc=0; \
	cargo test --manifest-path core/Cargo.toml || { echo "[!] FAILED: cargo test"; rc=1; }; \
	npm --prefix cli run test:cli || { echo "[!] FAILED: CLI suite"; rc=1; }; \
	npm --prefix cli run test:scope || { echo "[!] FAILED: terminal scope"; rc=1; }; \
	bash scripts/security_gates.sh || { echo "[!] FAILED: security gates"; rc=1; }; \
	node --test scripts/precommit-review.test.mjs || { echo "[!] FAILED: pre-commit review gate tests"; rc=1; }; \
	if [ $$rc -ne 0 ]; then echo "[!] make test: one or more steps failed (all steps ran)"; fi; \
	exit $$rc

test-fixture-notice:
	@if [ -z "$$NEXUS_EVAL_TEST_WORKSPACE_ROOT" ] || [ -z "$$NEXUS_EVAL_TEST_RUNTIME_ROOT" ]; then \
	  echo "[i] NEXUS_EVAL_TEST_WORKSPACE_ROOT / NEXUS_EVAL_TEST_RUNTIME_ROOT are not set."; \
	  echo "[i] cli/test/eval_version_probe_storage.test.ts will FAIL without them, and cli/test/eval_integrity.test.ts"; \
	  echo "[i] runs its /dev/shm fallback branches instead of the capped-tmpfs ones. This is not a code defect."; \
	  echo "[i] Run 'make test-ci' to provision the same fixtures as CI (needs sudo)."; \
# Project Guidelines & Agent Instructions

## Commands
- Build: `make build` or `cargo build` or `npm run build`
- Test: `make test` or `cargo test` or `npm test`
- Lint: `cargo clippy` or `npm run lint`

## Code Conventions
- Maintain documentation integrity and keep existing comments.
- Always run tests after making changes to verify correctness.
- Keep functions modular and clearly typed.

## Entire CLI
- Set `ENTIRE_TOKEN_STORE=file` in the environment before running any `entire` command (for example, `export ENTIRE_TOKEN_STORE=file`).

## v1.0.0 work and concurrent agents
- The v1.0.0 plan is in `docs/v1.0.0/` (start at `docs/v1.0.0/README.md`). Implement one claimed PR slice at a time, within the safe change boundary in its plan.
- When more than one agent may be working, follow `docs/v1.0.0/CONCURRENCY.md`. In short:
  - Claim the slice atomically under `$(git rev-parse --git-common-dir)/nexus-claims/`.
  - Use one worktree and branch per slice; never edit `~/nexus-code` directly.
  - Isolate `HOME` for every test or probe run.
  - Claim hot files before editing them.
  - Take the `GATEWAY` claim for any inference run.
  - Never use `pkill -f`.
  - Check `git log` for foreign commits before every commit.
  - Leave push, tag and publish to the owner.
